mapper.insert:

	SELECT SEQ_PAYMENT_NUMBER.NEXTVAL FROM DUAL

INSERT INTO payment(
	    payment_number
	  , medical_number
      , payment_type
	  , payment_date
	  , total_amount
      , payment_status
) VALUES (
	    #{paymentNumber}
	  , #{medicalNumber}
	  , #{paymentType}
	  , SYSDATE
	  , #{totalAmount}
	  , '수납완료'
)

INSERT INTO payment_history (
    payment_number
    , medical_number
    , line_no
    , payment_detail_name
    , amount
) VALUES (
      #{paymentNumber}
    , #{medicalNumber}
    , #{lineNo}
    , #{paymentDetailName}
    , #{amount}
)
